/**
 * Segmented tab bar with a sliding indicator.
 *
 * The indicator is measured from the live DOM, so the bar works at any width
 * and re-measures on resize / font load / container reflow.
 */
import { el, haptic } from '../dom';

export interface TabItem {
  id: string;
  label: string;
  /** Raw inline `<svg>` markup shown before the label. */
  icon?: string;
}

export interface TabsController {
  el: HTMLElement;
  /** Programmatically select a tab. Does not fire `onChange`. */
  select(id: string): void;
  /** Current tab id. */
  readonly current: string;
  dispose(): void;
}

export function tabs(
  items: TabItem[],
  onChange: (id: string) => void,
  initial?: string,
): TabsController {
  const root = el('div', {
    class: 'tabs tabs--stretch',
    attrs: { role: 'tablist' },
  });

  const indicator = el('div', { class: 'tabs__ind', aria: { hidden: 'true' } });
  root.appendChild(indicator);

  const buttons = new Map<string, HTMLButtonElement>();
  let current = initial && items.some((i) => i.id === initial) ? initial : (items[0]?.id ?? '');

  const place = (): void => {
    const btn = buttons.get(current);
    if (!btn) return;
    const w = btn.offsetWidth;
    if (w <= 0) return;
    indicator.style.width = `${w}px`;
    indicator.style.transform = `translateX(${btn.offsetLeft}px)`;
  };

  const apply = (id: string): void => {
    current = id;
    for (const [key, btn] of buttons) {
      const on = key === id;
      btn.classList.toggle('tab--on', on);
      btn.setAttribute('aria-selected', on ? 'true' : 'false');
      btn.tabIndex = on ? 0 : -1;
    }
    place();
  };

  for (const item of items) {
    const btn = el('button', {
      class: 'tab',
      attrs: { type: 'button', role: 'tab' },
      data: { tab: item.id },
    });
    if (item.icon) btn.insertAdjacentHTML('beforeend', item.icon);
    btn.appendChild(el('span', { class: 'tab__label', text: item.label }));
    btn.addEventListener('click', () => {
      if (current === item.id) return;
      haptic(9);
      apply(item.id);
      onChange(item.id);
    });
    buttons.set(item.id, btn);
    root.appendChild(btn);
  }

  apply(current);

  // Measure once the bar is actually laid out, then keep it in sync.
  const ro = new ResizeObserver(() => place());
  ro.observe(root);
  requestAnimationFrame(place);
  window.setTimeout(place, 120);

  return {
    el: root,
    select(id: string): void {
      if (!buttons.has(id) || id === current) {
        if (buttons.has(id)) place();
        return;
      }
      apply(id);
    },
    get current(): string {
      return current;
    },
    dispose(): void {
      ro.disconnect();
    },
  };
}

